def filter_by_substring_recursive(strings: List[str], substring: str) -> List[str]:
    """ Filter an input list of strings only for ones that contain given substring
    >>> filter_by_substring_recursive([], 'a')
    []
    >>> filter_by_substring_recursive(['abc', 'bacd', 'cde', 'array'], 'a')
    ['abc', 'bacd', 'array']
    """
    if not strings:
        return []
    if substring in strings[0]:
        return [strings[0]] + filter_by_substring_recursive(strings[1:], substring)
    return filter_by_substring_recursive(strings[1:], substring)


def filter_by_substring_iterative(strings: List[str], substring: str) -> List[str]:
    """ Filter an input list of strings only for ones that contain given substring
    >>> filter_by_substring_iterative([], 'a')
    []
    >>> filter_by_substring_iterative(['abc', 'bacd', 'cde', 'array'], 'a')
    ['abc', 'bacd', 'array']
    """
    filtered_list = []
    for string in strings:
        if substring in string:
            filtered_list.append(string

    res = []
    for s in strings:
        if substring in s:
            res.append(s)
    return res


