def is_balanced_group(group: str) -> (bool, str):
    """ Takes a group of nested parentheses and decides if it's balanced.
    A group is balanced if each open brace is closed
    Does not handle nested groups properly
    >>> is_balanced_group(' ( ) (( )( ))')
    (True, ' () (( )()) ')
    """
    if not group:
        return True, ''
    paren_map = {'(': ')', ')': '('}
    open_braces = []
    for c in group:
        if c not in paren_map:
            continue
        if not open_braces or paren_map[c] != open_braces[-1]:
            return False, ''
        open_braces.pop()
    if open_braces:
        return False, ''
    balanced_group = group.strip()
    return True, balanced_group


